from lib import *
S = SS('f78')
R = J('f78'); up = R['upg']; mq = list(R['mq'].values()); rtt = R['rtt']; kill = R['kill']; stop = R['stop']
steps = [
    step("握手的原始样子:普通 HTTP GET /socket.io/?EIO=4&transport=polling 返回 200,正文是 0{\"sid\":...,\"upgrades\":[\"websocket\"],\"pingTimeout\":20000,\"pingInterval\":25000,\"maxPayload\":1000000}(开头的 0 是 Engine.IO 的 OPEN 包)。带这个 sid POST 40(Socket.IO 的 CONNECT 包)得到 OK,再轮询取回 40{\"sid\":...}(Socket.IO 自己的 sid,和 Engine.IO 的不同);发带 ack 编号的事件 421[\"echo\",\"hi\"],轮询取回 431[{...}](43 是 ACK 包);用不存在的 sid 轮询返回 400「Invalid session nope」。", t=tl(S(1)), done=lidx(S(1), '正文', 'POST 40', '轮询取回', '421'), mark=lidx(S(1), 'Invalid session'), kv=KV([['0{...}', 'Engine.IO OPEN,含 pingInterval 25000 / pingTimeout 20000'], ['40 / 42 / 43', 'CONNECT / EVENT / ACK']], ['0{...}'])),
    step(f"python-socketio 客户端用 transports=['polling', 'websocket']:服务端日志里这次连接是 transport=polling(先经轮询建立),而 connect() 在 +{up[0][0]} ms 返回时传输方式已经是 websocket(升级在 connect 内完成了)。只允许 websocket 时直接是 websocket;只允许 polling 时 1.5 秒后仍是 polling,不会升级。", t=tl(S(2)), done=lidx(S(2), 'connect() 返回时', '服务端事件日志'), mark=lidx(S(2), '只允许'), kv=KV([['默认', '先 polling 再升级 websocket'], ['transports=[websocket]', '直接 websocket'], ['transports=[polling]', '不升级']], ['默认'])),
    step("事件与 ack:c.call('echo', {a:1}) 的返回值是服务端处理函数的 return(含 worker 的 pid);服务端 emit 回来的 joined 事件客户端用 on 收到。连接时 auth 数据传到 connect 处理函数,处理函数 return False 拒绝连接,客户端 connect 抛 ConnectionError: One or more namespaces failed to connect: /。", t=tl(S(3)), done=lidx(S(3), 'call(', 'joined'), mark=lidx(S(3), 'return False'), kv=KV([['处理函数 return', '作为 ack 返回给客户端'], ['connect 返回 False', '拒绝连接']], ['connect 返回 False'])),
    step("房间与广播(A、B 加入 r1,C 没加入):A 向 r1 发 m1(include_self=True)→ A、B 收到,C 没有;include_self=False 的 m2 → 只有 B;广播 bcast(include_self=False)→ B 和 C 都收到、A 没有。", t=tl(S(4)), done=lidx(S(4), 'm1', 'm2'), mark=lidx(S(4), '广播'), kv=KV([['to=房间', '只发给房间里的客户端'], ['include_self=False', '不发给发送者']], ['to=房间'])),
    step(f"断线检测(服务端 ping_interval=1 秒、ping_timeout=1 秒):客户端主动 disconnect() → reason=transport close;kill -9 客户端进程,系统关掉 TCP 连接,服务端 {kill[0]:.2f} 秒后就触发 disconnect(reason={kill[1]});SIGSTOP 冻住客户端(进程在、连接没关、不回应 ping),要等 {stop[0]:.2f} 秒才触发,reason={stop[1]}。真正的半开连接(比如断网)要靠 ping 超时来发现。", b=bars([['kill -9(连接被关)', kill[0], f'{kill[0]:.2f} s'], ['SIGSTOP(不回应 ping)', stop[0], f'{stop[0]:.2f} s']], 2.2, mark=[1], done=[0]), t=tl(S(5)), done=lidx(S(5), '主动', 'kill -9'), mark=lidx(S(5), 'SIGSTOP'), kv=KV([['连接被关', '立刻 transport close'], ['不回应 ping', f'约 {stop[0]:.1f} s 后 ping timeout']], ['不回应 ping'])),
    step(f"2 个 gunicorn worker、8 个 websocket 客户端:没有 message_queue 时,A 广播(不含自己)只有同一个 worker 上的客户端收到——收到 {mq[0][1]} 个(最多 7);配上自己起的 redis 作为 message_queue,收到 {mq[1][1]} 个。客户端在 worker 间的分布是随机的(这两次分别是 {mq[0][0]} 与 {mq[1][0]})。", b=bars([['无 message_queue', mq[0][1], f'{mq[0][1]} / 7'], ['redis message_queue', mq[1][1], f'{mq[1][1]} / 7']], 7, mark=[0], done=[1]), t=tl(S(6)), mark=lidx(S(6), '无 message_queue'), done=lidx(S(6), 'redis'), kv=KV([['多 worker 无队列', '广播只到本 worker'], ['message_queue', 'worker 间通过 redis 转发']], ['多 worker 无队列'])),
    step(f"同一个 echo 事件的往返:本机、50 次取中位数,polling {rtt['polling'][0]:.2f} ms,websocket {rtt['websocket'][0]:.2f} ms(约 {rtt['polling'][0] / rtt['websocket'][0]:.1f} 倍)。轮询每次都是一个完整的 HTTP 请求。", b=bars([['polling', rtt['polling'][0], f"{rtt['polling'][0]:.2f} ms"], ['websocket', rtt['websocket'][0], f"{rtt['websocket'][0]:.2f} ms"]], rtt['polling'][0], mark=[0], done=[1]), t=tl(S(7)), done=lidx(S(7), 'websocket'), kv=KV([['polling', f"{rtt['polling'][0]:.2f} ms"], ['websocket', f"{rtt['websocket'][0]:.2f} ms"]], ['websocket'])),
]
A = mkartf('f78', 78, 'Flask,Flask-SocketIO,WebSocket,长连接,真实验证,动画演示',
    f'实测 Flask-SocketIO:握手的原始数据包(OPEN、CONNECT、EVENT、ACK)、先轮询再升级 websocket、事件与 ack、拒绝连接、房间与广播、kill -9 与 SIGSTOP 两种断线的检测时间({kill[0]:.2f} s 对 {stop[0]:.2f} s)、2 个 worker 下无 message_queue 广播只到 {mq[0][1]} 个客户端、polling 与 websocket 的往返延迟。',
    'Flask-SocketIO 的长连接到底是怎么建立的?服务端怎么知道客户端掉线了?多 worker 部署时广播为什么会丢?这篇用真实的 gunicorn、python-socketio 客户端和自己起的 redis,把握手包、断线时间和广播范围逐项打印出来。',
    [(f'{stop[0]:.2f} s', '客户端不再回应 ping 后(ping_interval 与 ping_timeout 各 1 秒),服务端触发 disconnect 的时间'), (f'{mq[0][1]} → {mq[1][1]}', '2 个 worker 下广播收到的客户端数(最多 7):无 message_queue 与 redis message_queue'), ('0 / 40 / 42 / 43', 'Engine.IO 与 Socket.IO 的 OPEN、CONNECT、EVENT、ACK 包类型')],
    [('握手与数据包', '<p>上一篇:<a href="flask-flask-mail.html">Flask-Mail</a>;下一篇:<a href="flask-flask-cors.html">Flask-CORS</a>。</p>'), ('先轮询再升级', None), ('事件、ack 与拒绝连接', None), ('房间与广播', None), ('断线检测', '<p>reason 的取值依赖库版本;这里只记录了 transport close 与 ping timeout 两种在本次实验里观察到的值。</p>'), ('多 worker 与 message_queue', '<p>客户端用的都是 websocket-only 传输。轮询传输在多 worker 下需要粘性会话,这一点本篇没有验证。</p>'), ('polling 与 websocket 的延迟', None)],
    steps, [ENV_F + '。Flask-SocketIO 5.6.1、python-socketio 5.17.0(服务端与客户端)、python-engineio 4.14.0、simple-websocket 1.1.0、gunicorn gthread worker、自己起的 redis', '没有验证:eventlet/gevent 异步模式、轮询传输下多 worker 的粘性会话问题、nginx 反向代理下的 WebSocket 升级配置(见部署篇)、大量并发连接的资源消耗、浏览器端 socket.io-client、命名空间与房间的持久化'], 'Flask-SocketIO 长连接', panels=[('t', 'term', '实验输出'), ('b', 'bars', '耗时 / 数量'), ('kv', 'kv', '要点')])
